#include "services/saleservice.h"
#include "database.h"
#include <QDateTime>
#include <QtSql/QSqlError>
#include <QtSql/QSqlQuery>
SaleTotals SalesService::calculate(const QVector<CartLine> &lines,int taxBp) { SaleTotals t;for(const auto &l:lines){t.subtotalCents+=l.product.priceCents*l.quantity;t.discountCents+=l.discountCents;}const qint64 taxable=t.subtotalCents-t.discountCents;t.taxCents=(taxable*taxBp+5000)/10000;t.totalCents=taxable+t.taxCents;return t; }
qint64 SalesService::checkout(const QVector<CartLine> &lines,int taxBp,qint64 paid,qint64 userId,QString *error) { if(lines.isEmpty()){if(error)*error="Cart is empty.";return 0;}auto t=calculate(lines,taxBp);if(paid<t.totalCents){if(error)*error="Cash tendered is less than the total.";return 0;}auto db=Database::connection();if(!db.transaction()){if(error)*error="Could not begin transaction.";return 0;} for(const auto&l:lines){if(l.quantity<1){db.rollback();if(error)*error="Invalid quantity.";return 0;}QSqlQuery stock(db);stock.prepare("UPDATE products SET stock_quantity=stock_quantity-? WHERE id=? AND is_active=1 AND stock_quantity>=?");stock.addBindValue(l.quantity);stock.addBindValue(l.product.id);stock.addBindValue(l.quantity);if(!stock.exec()||stock.numRowsAffected()!=1){db.rollback();if(error)*error="Insufficient stock for "+l.product.name;return 0;}}
QSqlQuery sale(db);sale.prepare("INSERT INTO sales(receipt_number,user_id,subtotal_cents,discount_cents,tax_cents,total_cents,paid_cents,change_cents) VALUES(?,?,?,?,?,?,?,?)");sale.addBindValue("R"+QDateTime::currentDateTimeUtc().toString("yyyyMMddhhmmsszzz"));sale.addBindValue(userId);sale.addBindValue(t.subtotalCents);sale.addBindValue(t.discountCents);sale.addBindValue(t.taxCents);sale.addBindValue(t.totalCents);sale.addBindValue(paid);sale.addBindValue(paid-t.totalCents);if(!sale.exec()){db.rollback();if(error)*error=sale.lastError().text();return 0;}qint64 id=sale.lastInsertId().toLongLong();for(const auto&l:lines){QSqlQuery item(db);item.prepare("INSERT INTO sale_items(sale_id,product_id,product_name,sku,unit_price_cents,quantity,discount_cents,line_total_cents) VALUES(?,?,?,?,?,?,?,?)");item.addBindValue(id);item.addBindValue(l.product.id);item.addBindValue(l.product.name);item.addBindValue(l.product.sku);item.addBindValue(l.product.priceCents);item.addBindValue(l.quantity);item.addBindValue(l.discountCents);item.addBindValue(l.subtotalCents());if(!item.exec()){db.rollback();if(error)*error=item.lastError().text();return 0;}QSqlQuery log(db);log.prepare("INSERT INTO inventory_transactions(product_id,delta,reason,user_id) VALUES(?,?,?,?)");log.addBindValue(l.product.id);log.addBindValue(-l.quantity);log.addBindValue("Sale #"+QString::number(id));log.addBindValue(userId);if(!log.exec()){db.rollback();return 0;}}if(!db.commit()){if(error)*error="Could not commit sale.";return 0;}return id; }
bool SalesService::refund(qint64 saleId,qint64 userId,QString *error) {auto db=Database::connection();if(!db.transaction())return false;QSqlQuery status(db);status.prepare("UPDATE sales SET status='refunded',refunded_at=CURRENT_TIMESTAMP WHERE id=? AND status='completed'");status.addBindValue(saleId);if(!status.exec()||status.numRowsAffected()!=1){db.rollback();if(error)*error="Sale is unavailable or already refunded.";return false;}QSqlQuery items(db);items.prepare("SELECT product_id,quantity FROM sale_items WHERE sale_id=?");items.addBindValue(saleId);if(!items.exec()){db.rollback();return false;}while(items.next()){QSqlQuery p(db);p.prepare("UPDATE products SET stock_quantity=stock_quantity+? WHERE id=?");p.addBindValue(items.value(1));p.addBindValue(items.value(0));if(!p.exec()){db.rollback();return false;}QSqlQuery log(db);log.prepare("INSERT INTO inventory_transactions(product_id,delta,reason,user_id) VALUES(?,?,?,?)");log.addBindValue(items.value(0));log.addBindValue(items.value(1));log.addBindValue("Refund #"+QString::number(saleId));log.addBindValue(userId);if(!log.exec()){db.rollback();return false;}}return db.commit();}
